//! Field-driven cinema — a film *generated by* an instrument, not one that
//! *depicts* one.
//!
//! The reaction cut's [`director`](../libgibson_intro_reaction/director.rs)
//! resolves each shot from **edit-clock time** against a hand-authored cue table:
//! the picture is a pure function of *when*, and reads no model state at all. That
//! is a film that depicts an instrument. This module is the deliberate inverse and
//! the v0.6 R6.1 slice (issue #191): every shot is a pure, deterministic function
//! of **observed field state + a probe/selection**, and the pixels on screen *are*
//! the field, rendered through the same [`FieldView`]/[`WorldView`]/[`Surface`]
//! pipeline the rest of the stack uses (Law L1 — one renderer, no second engine).
//!
//! The causal chain, one direction only, no clock and no RNG on the frame path:
//!
//! ```text
//!   model(tick) ──► field data ──► FieldView ──► observe() ──► FieldObservation
//!                                        │                            │
//!                                     probe(sel) ──► ProbeReport ──────┤
//!                                                                      ▼
//!                                                                  compose()
//!                                                                      │
//!                                                                      ▼
//!                      render_shot(FieldView, Shot) ──► FieldFrame (Surface + receipt)
//! ```
//!
//! Change the model or the selection and the shot — and the painted pixels —
//! change (the dependency is positive and *specific*). The instrument observes the
//! *whole* field, so a dominating sample anywhere — even outside the current frame
//! — pulls the camera to it; what the grammar provably *never* reads is a
//! **masked** cell's hidden value, so perturbing one moves nothing. The dependency
//! is scoped to observed data, not the vacuous "everything perturbs everything",
//! and not the opposite over-claim that the camera only sees its own ROI. Replay
//! the same `(tick, selection)` and the `Surface` is byte-identical (Law L10 —
//! replayable, claims scoped to evidence). `tests/field_cinema_mutation.rs` proves
//! each of these — the positive field/selection/global dependencies, the
//! masked-cell non-dependency, and determinism — and proves the battery itself has
//! teeth by showing a field-blind grammar would fail the positive dependency check.
//!
//! No audio, no third-party media, pure terminal cells: the v0.5 distribution
//! boundary is preserved and the soundtrack is silence.

#![allow(dead_code)] // some items exist only for the mutation-test consumer.

use gibson::field_view::{
    Colormap, FieldExtent, FieldFrame, FieldView, ProbeReport, RangePolicy, Sample,
};
use gibson::shape::Point;
use gibson::world_view::WorldView;
use gibson::Rect;

// ---------------------------------------------------------------------------
// Source identity
// ---------------------------------------------------------------------------

/// A model's stable source identity (the producer the frames are attributed to).
/// Carried through the observation and baked into the shot caption as provenance;
/// it never fabricates a pixel.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct SourceId(pub u32);

// ---------------------------------------------------------------------------
// The synthetic model — owns the data, the units, and the logical clock
// ---------------------------------------------------------------------------

/// Field width in cells / world units (origin at 0, one world unit per cell).
pub const COLS: usize = 48;
/// Field height in cells / world units.
pub const ROWS: usize = 24;

/// A deterministic synthetic instrument: it emits a source-identified scalar
/// field that evolves over a logical tick. A traveling Gaussian hotspot sweeps the
/// grid, a static quiet lobe anchors one corner, and a fixed rectangular
/// sensor-dropout patch is marked absent in the presence mask. Every reading is a
/// pure function of `tick`: no wall-clock, no RNG.
pub struct Model {
    source: SourceId,
    epoch: u32,
    extent: FieldExtent,
}

impl Model {
    /// A model with the fixed grid geometry. The geometry is static and valid, so
    /// the extent is always constructible.
    pub fn new(source: SourceId, epoch: u32) -> Self {
        let extent = FieldExtent::new(Point::new(0.0, 0.0), 1.0, 1.0, COLS, ROWS)
            .expect("static COLS/ROWS geometry is always a valid extent");
        Self {
            source,
            epoch,
            extent,
        }
    }

    /// The source this model's frames are attributed to.
    pub fn source(&self) -> SourceId {
        self.source
    }
    /// The model's epoch (advances on a conceptual restart; static here).
    pub fn epoch(&self) -> u32 {
        self.epoch
    }
    /// The field geometry.
    pub fn extent(&self) -> FieldExtent {
        self.extent
    }

    /// The traveling hotspot's world center at `tick` — a deterministic sweep
    /// left→right with a gentle vertical bob. The x march is strictly increasing
    /// within a tick window, so a later tick frames the peak further right (the
    /// property the positive field-dependency test leans on).
    pub fn hotspot_center(&self, tick: u64) -> Point {
        let travel = COLS as f64 - 12.0; // keep the peak clear of both x edges
        let x = 6.0 + ((tick as f64) * 1.3) % travel;
        let y = ROWS as f64 / 2.0 + 5.0 * ((tick as f64) * 0.21).sin();
        Point::new(x, y)
    }

    /// The field data at `tick`, row-major, length `COLS*ROWS`. A pure function of
    /// `tick`: baseline + a unit-amplitude traveling Gaussian + a static quiet
    /// lobe. Deterministic and finite everywhere.
    pub fn field_data(&self, tick: u64) -> Vec<f64> {
        let c = self.hotspot_center(tick);
        let q = Point::new(COLS as f64 - 8.0, 5.0); // static quiet lobe
        let peak_sigma2 = 2.0 * 3.0 * 3.0; // sigma = 3 cells
        let lobe_sigma2 = 2.0 * 2.0 * 2.0; // sigma = 2 cells
        let mut data = vec![0.0f64; COLS * ROWS];
        for iy in 0..ROWS {
            for ix in 0..COLS {
                let x = ix as f64 + 0.5;
                let y = iy as f64 + 0.5;
                let d2 = (x - c.x).powi(2) + (y - c.y).powi(2);
                let dq2 = (x - q.x).powi(2) + (y - q.y).powi(2);
                data[iy * COLS + ix] =
                    0.1 + (-d2 / peak_sigma2).exp() + 0.35 * (-dq2 / lobe_sigma2).exp();
            }
        }
        data
    }

    /// The static presence mask: a rectangular sensor-dropout patch (cols 2..8,
    /// rows 16..22) is marked absent. The data under a masked cell is *never*
    /// observed (Masked wins over value), which is exactly what the decoy /
    /// negative-control test exploits to prove the shot does not read it.
    pub fn mask(&self) -> Vec<bool> {
        let mut m = vec![true; COLS * ROWS];
        for iy in 16..22 {
            for ix in 2..8 {
                m[iy * COLS + ix] = false;
            }
        }
        m
    }

    /// Convenience: a borrowable `FieldView` over freshly built `data`/`mask`.
    /// The caller owns the buffers so the view can be re-observed and re-rendered.
    pub fn frame_buffers(&self, tick: u64) -> (Vec<f64>, Vec<bool>) {
        (self.field_data(tick), self.mask())
    }
}

// ---------------------------------------------------------------------------
// Observation — derived PURELY from a FieldView (the only state the shot reads)
// ---------------------------------------------------------------------------

/// What the director is allowed to know about a frame. Every field here is
/// computed from the [`FieldView`] alone (plus the carried provenance), so the
/// shot cannot depend on anything the instrument did not actually observe.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct FieldObservation {
    /// Provenance — carried for the caption, never used to synthesize a pixel.
    pub source: SourceId,
    pub epoch: u32,
    pub tick: u64,
    /// World center of the strongest finite, unmasked cell (the active region).
    pub peak_center: Option<Point>,
    /// The value at that peak cell.
    pub peak_value: Option<f64>,
    /// `hi - lo` over finite unmasked samples (0 if there are none): the dynamic
    /// range the shot frames against.
    pub range_span: f64,
    /// Fraction of cells reported absent by the mask.
    pub masked_fraction: f64,
}

/// Observe a field: scan for the strongest unmasked finite cell, the dynamic
/// range, and the masked fraction. Pure in the view's data; scan order fixes ties
/// deterministically (first cell wins on an exact tie).
pub fn observe(view: &FieldView, source: SourceId, epoch: u32, tick: u64) -> FieldObservation {
    let e = view.extent();
    let total = e.len();
    let mut best: Option<(f64, (usize, usize))> = None;
    let mut masked = 0usize;
    for iy in 0..e.rows() {
        for ix in 0..e.cols() {
            match view.sample(ix, iy) {
                Some(Sample::Value(v)) => {
                    if best.is_none_or(|(bv, _)| v > bv) {
                        best = Some((v, (ix, iy)));
                    }
                }
                Some(Sample::Masked) => masked += 1,
                _ => {}
            }
        }
    }
    let (peak_value, peak_center) = match best {
        Some((v, (ix, iy))) => (Some(v), e.cell_center(ix, iy)),
        None => (None, None),
    };
    let range_span = view.finite_extremes().map_or(0.0, |(lo, hi)| hi - lo);
    FieldObservation {
        source,
        epoch,
        tick,
        peak_center,
        peak_value,
        range_span,
        masked_fraction: masked as f64 / total.max(1) as f64,
    }
}

// ---------------------------------------------------------------------------
// The shot + the compositional grammar
// ---------------------------------------------------------------------------

/// How the selection modulates the framing — the probe-driven beat.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Emphasis {
    /// The selection is off the active region; the shot holds its base framing.
    Wide,
    /// The selection sits on a strong sample; the camera punches in on it.
    PunchIn,
}

/// A fully resolved shot — a deterministic function of one observation and one
/// probe. `zoom` is raster pixels per world unit (larger = tighter).
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Shot {
    /// World point the camera centers on.
    pub focus: Point,
    /// Pixels per world unit (framing tightness).
    pub zoom: f64,
    /// Presentation ramp chosen for the frame.
    pub colormap: Colormap,
    /// The selection-driven beat.
    pub emphasis: Emphasis,
    /// Provenance, baked into the caption.
    pub source: SourceId,
    pub epoch: u32,
    pub tick: u64,
    /// The finite value under the probe, if any (the inspector's reading).
    pub probe_reading: Option<f64>,
}

/// Base (widest) zoom in pixels per world unit.
pub const WIDE_ZOOM: f64 = 1.0;
/// Extra zoom per unit of normalized dynamic range.
pub const SPAN_ZOOM_GAIN: f64 = 0.8;
/// Reference span the range is normalized against.
pub const SPAN_REFERENCE: f64 = 1.2;
/// Masked-fraction above which the frame falls back to the colour-free ramp.
pub const DROPOUT_DENSITY_THRESHOLD: f64 = 0.10;
/// Probe reading (as a fraction of the peak) at or above which the shot punches in.
pub const PUNCH_PEAK_FRACTION: f64 = 0.6;
/// Zoom multiplier applied by a punch-in.
pub const PUNCH_ZOOM_MUL: f64 = 1.5;

/// Compose a shot from an observation and a probe. Four compositional rules, each
/// mapping one observable to one shot parameter; no clock, no RNG, no hidden
/// state. This is the entire cinematic grammar.
pub fn compose(obs: &FieldObservation, probe: &ProbeReport, extent: FieldExtent) -> Shot {
    // Rule 1 — focus follows the model's active region (the peak), else the field
    // center when there is nothing finite to look at.
    let focus = obs.peak_center.unwrap_or_else(|| field_center(extent));

    // Rule 2 — dynamic range frames the shot: a stronger peak over its floor zooms
    // tighter, within [WIDE_ZOOM, WIDE_ZOOM + SPAN_ZOOM_GAIN].
    let span_norm = (obs.range_span / SPAN_REFERENCE).clamp(0.0, 1.0);
    let mut zoom = WIDE_ZOOM + SPAN_ZOOM_GAIN * span_norm;

    // Rule 3 — missing data chooses an honest presentation: heavy dropout drops to
    // the colour-free density ramp so intensity survives with no colour at all.
    let colormap = if obs.masked_fraction > DROPOUT_DENSITY_THRESHOLD {
        Colormap::Density
    } else {
        Colormap::Heat
    };

    // Rule 4 — the selection drives the beat: a probe landing on a strong sample
    // (relative to the observed peak) punches the camera in on it.
    let probe_reading = match probe.sample {
        Some(Sample::Value(v)) => Some(v),
        _ => None,
    };
    let on_peak = match (probe_reading, obs.peak_value) {
        (Some(pv), Some(peak)) => peak > 0.0 && pv >= PUNCH_PEAK_FRACTION * peak,
        _ => false,
    };
    let emphasis = if on_peak {
        zoom *= PUNCH_ZOOM_MUL;
        Emphasis::PunchIn
    } else {
        Emphasis::Wide
    };

    Shot {
        focus,
        zoom,
        colormap,
        emphasis,
        source: obs.source,
        epoch: obs.epoch,
        tick: obs.tick,
        probe_reading,
    }
}

/// The world center of a field extent.
pub fn field_center(e: FieldExtent) -> Point {
    Point::new(
        e.origin().x + e.cols() as f64 * e.cell_w() / 2.0,
        e.origin().y + e.rows() as f64 * e.cell_h() / 2.0,
    )
}

// ---------------------------------------------------------------------------
// Staging — resolve a shot into a framed WorldView and render the field through it
// ---------------------------------------------------------------------------

/// Build a [`WorldView`] that centers `focus` in `anchor` at `zoom` pixels per
/// world unit, using the common 1×2 pixels-per-cell terminal grouping. A
/// degenerate (non-finite or non-positive) zoom falls back to [`WIDE_ZOOM`] rather
/// than producing a non-invertible view.
pub fn view_focused_on(focus: Point, zoom: f64, anchor: Rect) -> WorldView {
    let z = if zoom.is_finite() && zoom > 0.0 {
        zoom
    } else {
        WIDE_ZOOM
    };
    let (ppc_x, ppc_y) = (1u16, 2u16);
    let rw = anchor.width as f64 * ppc_x as f64;
    let rh = anchor.height as f64 * ppc_y as f64;
    // world_to_view(focus) == (rw/2, rh/2)  ⇒  pan = focus - (raster/2)/zoom.
    let pan_x = focus.x - (rw / 2.0) / z;
    let pan_y = focus.y - (rh / 2.0) / z;
    WorldView::new(anchor)
        .with_zoom(z, z)
        .with_pixels_per_cell(ppc_x, ppc_y)
        .with_pan(pan_x, pan_y)
}

/// Render the field through the shot's framing. The pixels are the field; the
/// framing (and the colormap) are the shot. The returned [`FieldFrame`] carries
/// the field_view conservation receipt unchanged.
pub fn render_shot(view: &FieldView, shot: &Shot, anchor: Rect) -> FieldFrame {
    let wv = view_focused_on(shot.focus, shot.zoom, anchor);
    view.render(&wv, anchor, shot.colormap, RangePolicy::Auto)
}

/// One fully staged frame: the observation it was composed from, the shot, and the
/// rendered field frame.
pub struct Staged {
    pub observation: FieldObservation,
    pub shot: Shot,
    pub frame: FieldFrame,
}

/// Stage a tick end to end: build the field, observe it, probe the selection,
/// compose the shot, render it. The whole pipeline, deterministic in
/// `(tick, probe_world)`.
pub fn stage_tick(model: &Model, tick: u64, probe_world: Point, anchor: Rect) -> Staged {
    let (data, mask) = model.frame_buffers(tick);
    let view = FieldView::new(model.extent(), &data, Some(&mask))
        .expect("model geometry matches its own data/mask lengths");
    let observation = observe(&view, model.source(), model.epoch(), tick);
    let probe = view.probe(probe_world);
    let shot = compose(&observation, &probe, model.extent());
    let frame = render_shot(&view, &shot, anchor);
    Staged {
        observation,
        shot,
        frame,
    }
}

/// A field-*blind* grammar used only to prove the mutation tests have teeth: it
/// ignores the observation entirely and returns a fixed shot. Under this grammar
/// the positive field-dependency check must FAIL (the focus never moves) — that
/// failure is what certifies the real grammar's passing is non-vacuous.
pub fn compose_blind(obs: &FieldObservation, _probe: &ProbeReport, extent: FieldExtent) -> Shot {
    Shot {
        focus: field_center(extent),
        zoom: WIDE_ZOOM,
        colormap: Colormap::Heat,
        emphasis: Emphasis::Wide,
        source: obs.source,
        epoch: obs.epoch,
        tick: obs.tick,
        probe_reading: None,
    }
}

// ---------------------------------------------------------------------------
// In-module unit laws (compiled only into the mutation-test target, excluded
// from the example binary build — see the #[path] include in tests/).
// ---------------------------------------------------------------------------

#[cfg(test)]
mod unit {
    use super::*;

    #[test]
    fn hotspot_marches_right_within_a_window() {
        let m = Model::new(SourceId(1), 1);
        // Within one sweep window (before the x wrap) a later tick is further right.
        let a = m.hotspot_center(1).x;
        let b = m.hotspot_center(5).x;
        assert!(
            b > a,
            "hotspot x must increase across early ticks: {a} !< {b}"
        );
    }

    #[test]
    fn focus_lands_at_the_raster_center() {
        // A focus centered in the anchor maps back to the center cell under the
        // staged WorldView (the framing math is self-consistent).
        let anchor = Rect::new(0, 0, 40, 20);
        let focus = Point::new(20.0, 10.0);
        let wv = view_focused_on(focus, 1.0, anchor);
        let (vx, vy) = wv.world_to_view(focus.x, focus.y);
        // raster center is (40*1/2, 20*2/2) = (20, 20).
        assert!((vx - 20.0).abs() < 1e-9, "focus x not centered: {vx}");
        assert!((vy - 20.0).abs() < 1e-9, "focus y not centered: {vy}");
    }

    #[test]
    fn blind_grammar_ignores_the_field() {
        let m = Model::new(SourceId(1), 1);
        let anchor = Rect::new(0, 0, 40, 20);
        let (d0, mk) = m.frame_buffers(0);
        let (d9, _) = m.frame_buffers(9);
        let v0 = FieldView::new(m.extent(), &d0, Some(&mk)).unwrap();
        let v9 = FieldView::new(m.extent(), &d9, Some(&mk)).unwrap();
        let o0 = observe(&v0, m.source(), m.epoch(), 0);
        let o9 = observe(&v9, m.source(), m.epoch(), 9);
        let p = v0.probe(field_center(m.extent()));
        let s0 = compose_blind(&o0, &p, m.extent());
        let s9 = compose_blind(&o9, &p, m.extent());
        let _ = anchor;
        assert_eq!(s0.focus, s9.focus, "blind grammar must not track the field");
    }
}
